# Step1: Extract the "Win–Loss" row
win_loss_row = df[df['Tournament'] == 'Win–Loss'].iloc[0]

# Step2: Parse the number of wins for each year
wins = {}
for year in ['2007', '2008', '2009', '2010', '2011', '2012', '2013', '2014']:
    if year in win_loss_row.index:
        win_loss = win_loss_row[year]
        if isinstance(win_loss, str) and '–' in win_loss:
            win, _ = win_loss.split('–')
            wins[year] = int(win)
        else:
            wins[year] = 0  # Default to 0 if not a valid "Win–Loss" string

# Step3: Find the year with the maximum number of wins
max_wins_year = max(wins, key=wins.get)

# Step4: Assign the final answer
final_answer_value = max_wins_year

